<script setup lang="ts">
import {computed,onMounted,onUnmounted,reactive,ref,watch} from 'vue'
import {client,type Asset,type Peer,type Profile,type Task} from '../sdk/client'
import {browserBridge} from '../platform/bridge'
import TaskAssets from './TaskAssets.vue'
const props=defineProps<{page:string;devices:Peer[];profiles:Profile[];assets:Asset[]}>()
const emit=defineEmits<{created:[task:Task];refresh:[]}>()
const busy=ref(false),error=ref(''),records=ref<any[]>([]),outreach=ref<any[]>([]),workflows=ref<any[]>([]),campaigns=ref<any[]>([]),chosen=ref<any>(),extras=ref<Asset[]>([]),review=ref(''),confirmed=ref(false)
const form=reactive({device_id:'',model_profile_id:'',account:'',mode:'followup',topic:'',prompt:'根据客户的问题，用自然、简洁的语气回复。先回答需求；没有依据的信息说明需要确认。不编造价格、库存、优惠，不重复追问已提供的信息。',knowledge:'',targets:'',max_records:10,max_replies:3,interval_seconds:30,add_friends:false,scheduled_at:'',repeat:false,interval_minutes:120,max_iterations:60})
const product=reactive({name:'',facts:'',audience:'',prompt:'突出真实卖点，避免夸大；设计商品详情页、小红书图文、场景图和短视频分镜。',asset_ids:[] as string[],ai_media:false})
const images=computed(()=>[...extras.value,...props.assets.filter(a=>!extras.value.some(e=>e.id===a.id))].filter(a=>a.mime==='image/png'||a.mime==='image/jpeg'))
const visibleRecords=computed(()=>records.value.filter(r=>props.page==='wechat'?r.platform==='wechat_crm':r.platform==='xhs_growth'))
const leads=computed(()=>visibleRecords.value.filter(r=>r.record.kind==='lead'))
const visibleOutreach=computed(()=>outreach.value.filter(r=>props.page==='wechat'?r.platform==='wechat_crm':r.platform==='xhs_growth'))
const visibleCampaigns=computed(()=>campaigns.value.filter(c=>props.page==='wechat'?c.spec.template==='wechat_crm':c.spec.template==='xhs_growth'))
const intent:Record<string,string>={unknown:'未知',low:'低',medium:'中',high:'高'}
let timer:ReturnType<typeof setInterval>|undefined
let pending:{payload:string;key:string}|undefined
watch(()=>props.page,p=>{form.mode=p==='wechat'?'followup':'draft';error.value='';chosen.value=undefined})
function keyFor(body:unknown){const payload=JSON.stringify(body);if(!pending||pending.payload!==payload)pending={payload,key:crypto.randomUUID()};return pending.key}
async function perform(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function reload(){const [r,o,w,c]=await Promise.all([client.request<any[]>('/business/records'),client.request<any[]>('/business/outreach'),client.request<any[]>('/materials'),client.request<any[]>('/campaigns')]);records.value=r;outreach.value=o;workflows.value=w;campaigns.value=c}
function spec(){return {template:props.page==='wechat'?'wechat_crm':'xhs_growth',mode:form.mode,device_id:form.device_id,model_profile_id:form.model_profile_id,account:form.account,max_iterations:form.max_iterations,asset_ids:[],scheduled_at:form.scheduled_at?new Date(form.scheduled_at).toISOString():undefined,business:{topic:form.topic,prompt:form.prompt,knowledge:form.knowledge,targets:form.targets.split('\n').map(v=>v.trim()).filter(Boolean),max_records:form.max_records,max_replies:form.max_replies,interval_seconds:form.interval_seconds,add_friends:props.page==='wechat'&&form.add_friends}}}
async function create(){await perform(async()=>{const body=spec();if(form.repeat){await client.post('/campaigns',{name:(props.page==='wechat'?'微信客服':'小红书运营')+' · '+form.account,spec:body,interval_minutes:form.interval_minutes});await reload()}else{const task=await client.post<Task>('/tasks',body,{'Idempotency-Key':keyFor(body)});pending=undefined;emit('created',task)}})}
async function upload(){await perform(async()=>{const files=await browserBridge.pickImages();if(product.asset_ids.length+files.length>9)throw Error('最多 9 张商品图');for(const file of files){if(file.size===0||file.size>16*1024*1024)throw Error('每张图需小于16 MB');const data=new FormData();data.append('file',file);const a=await client.request<Asset>('/assets',{method:'POST',body:data});extras.value.unshift(a);product.asset_ids.push(a.id)}emit('refresh')})}
function choose(w:any){chosen.value=w;review.value=w.result.content?JSON.stringify(w.result.content,null,2):'';confirmed.value=false}
async function generate(){await perform(async()=>{const body={...product,model_profile_id:form.model_profile_id};const w=await client.post<any>('/materials',body,{'Idempotency-Key':keyFor(body)});pending=undefined;choose(w);const result=await client.post<any>('/materials/'+w.id+'/generate',{});choose(result);await reload();emit('refresh')})}
async function renderEdited(){await perform(async()=>{const content=JSON.parse(review.value);const w=await client.post<any>('/materials/'+chosen.value.id+'/generate',{content});choose(w);await reload();emit('refresh')})}
async function retry(w:any){await perform(async()=>{choose(await client.post<any>('/materials/'+w.id+'/generate',{}));await reload();emit('refresh')})}
async function draft(){await perform(async()=>{if(!confirmed.value)throw Error('请先核对商品文案和图片');const task=await client.post<Task>('/materials/'+chosen.value.id+'/draft',{device_id:form.device_id,account:form.account,confirmed:true});emit('created',task)})}
async function toggle(c:any){await perform(async()=>{await client.request('/campaigns/'+c.id,{method:'PATCH',body:JSON.stringify({enabled:!c.enabled})});await reload()})}
onMounted(()=>{form.mode=props.page==='wechat'?'followup':'draft';reload().catch(e=>error.value=e.message);timer=setInterval(()=>{if(!busy.value)reload().catch(()=>{})},10000)})
onUnmounted(()=>{if(timer)clearInterval(timer)})
</script>
<template>
 <el-alert v-if="error" :title="error" type="error" :closable="false" class="notice"/>
 <div class="panel business-form">
  <div class="section-title"><h2>{{page==='commerce'?'电商单品素材工作流':page==='wechat'?'微信 AI 客服任务':'小红书获客与账号运维'}}</h2><el-button :loading="busy" @click="perform(reload)">刷新结果</el-button></div>
  <el-form label-position="top"><div class="form-grid"><el-form-item label="手机"><el-select v-model="form.device_id"><el-option v-for="d in devices" :key="d.id" :value="d.id" :label="d.name+(d.online?' · 在线':' · 离线')"/></el-select></el-form-item><el-form-item label="模型配置"><el-select v-model="form.model_profile_id"><el-option v-for="p in profiles" :key="p.id" :value="p.id" :label="p.name"/></el-select></el-form-item></div>
   <el-form-item label="指定账号（填写个人资料页实际名称）"><el-input v-model="form.account" placeholder="任务开始时核对个人资料页"/></el-form-item>
   <template v-if="page!=='commerce'">
    <el-form-item label="执行目标"><el-select v-model="form.mode"><template v-if="page==='wechat'"><el-option label="跟进指定客户 / 加好友" value="followup"/><el-option label="处理会话列表中的客户消息" value="inbox"/></template><template v-else><el-option label="主题搜索 → 热帖与需求研究" value="research"/><el-option label="主题搜索 → 原创图文 → 手机草稿" value="draft"/><el-option label="搜索热帖 → 回复有需求的评论" value="reply"/><el-option label="自己账号 → 评论通知回复" value="operate"/></template></el-select></el-form-item>
    <el-form-item v-if="page==='growth'&&form.mode!=='operate'" label="搜索主题"><el-input v-model="form.topic" placeholder="例如：电商单品图拍摄、微信客户跟进"/></el-form-item>
    <el-form-item :label="page==='wechat'?'客户名单（每行一个微信号或备注名）':'限定回复对象（可选，每行一个名称）'"><el-input v-model="form.targets" type="textarea" :rows="3"/></el-form-item>
    <el-form-item v-if="page==='wechat'"><el-checkbox v-model="form.add_friends">允许向名单中的客户发送好友申请</el-checkbox></el-form-item>
    <el-form-item label="回复提示词"><el-input v-model="form.prompt" type="textarea" :rows="4" maxlength="8000"/></el-form-item>
    <el-form-item label="业务知识 / 商品规格 / 常见问题"><el-input v-model="form.knowledge" type="textarea" :rows="4" maxlength="12000" placeholder="提供可使用的真实资料；未知内容交给人工确认"/></el-form-item>
    <div class="form-grid"><el-form-item label="单轮最多记录"><el-input-number v-model="form.max_records" :min="1" :max="100"/></el-form-item><el-form-item label="单轮最多发送（0 为仅收集）"><el-input-number v-model="form.max_replies" :min="0" :max="20"/></el-form-item><el-form-item label="发送间隔 / 秒"><el-input-number v-model="form.interval_seconds" :min="15" :max="3600"/></el-form-item><el-form-item label="手机操作轮数上限"><el-input-number v-model="form.max_iterations" :min="1" :max="100"/></el-form-item></div>
    <el-form-item><el-checkbox v-model="form.repeat">定时重复运行</el-checkbox></el-form-item><el-form-item v-if="form.repeat" label="每隔多少分钟"><el-input-number v-model="form.interval_minutes" :min="15" :max="10080"/><p class="subtle">上一轮等待接管或核验时不启动下一轮，避免堆积和重复回复。</p></el-form-item><el-form-item v-else label="执行时间（可选）"><el-input v-model="form.scheduled_at" type="datetime-local"/></el-form-item>
    <p class="subtle">帖子热度、联系方式和需求判断均保存页面证据。遇到登录、验证码或无法核验的页面，任务等待接管。草稿内容生成后创建独立手机草稿任务。</p><el-button type="primary" :loading="busy" @click="create">{{form.repeat?'创建定时运营计划':'创建手机任务'}}</el-button>
   </template>
   <template v-else>
    <el-form-item label="商品名称"><el-input v-model="product.name"/></el-form-item><el-form-item label="真实规格与卖点"><el-input v-model="product.facts" type="textarea" :rows="5" placeholder="材质、尺寸、功能、价格、使用场景等。只填写已确认的信息。"/></el-form-item><el-form-item label="目标用户"><el-input v-model="product.audience"/></el-form-item><el-form-item label="素材风格与要求"><el-input v-model="product.prompt" type="textarea" :rows="3"/></el-form-item>
    <el-form-item label="真实商品图（1–9 张）"><TaskAssets v-model="product.asset_ids" :assets="images" :image-only="true" :busy="busy" @upload="upload"/></el-form-item><el-form-item><el-checkbox v-model="product.ai_media">调用已配置的 AI 场景图与视频生成服务</el-checkbox></el-form-item><p class="subtle">生成商品详情页 PNG、小红书图文 PNG、商品场景排版图和静音 MP4 图片短视频。AI 场景图 / 视频需要管理员配置生成服务，未配置时会给出明确错误。</p><el-button type="primary" :loading="busy" @click="generate">生成全部素材</el-button>
   </template>
  </el-form>
 </div>
 <template v-if="page==='commerce'">
  <div class="panel business-form"><h2>素材工作流</h2><el-table :data="workflows" @row-click="choose"><el-table-column label="商品"><template #default="{row}">{{row.spec.name}}</template></el-table-column><el-table-column prop="status" label="状态"/><el-table-column prop="error" label="执行问题"/><el-table-column label="操作"><template #default="{row}"><el-button size="small" @click.stop="choose(row)">查看</el-button><el-button v-if="row.status==='failed'||row.status==='queued'" size="small" :disabled="busy" @click.stop="retry(row)">重试生成</el-button></template></el-table-column></el-table></div>
  <div v-if="chosen" class="panel business-form"><h2>{{chosen.spec.name}} · {{chosen.status}}</h2><p v-if="chosen.error" class="error">{{chosen.error}}</p><template v-if="chosen.status==='ready'"><p v-for="w in chosen.result.warnings" :key="w" class="subtle">{{w}}</p><h3>{{chosen.result.content.title}}</h3><p style="white-space:pre-wrap">{{chosen.result.content.body}}</p><p class="subtle">待核对：{{chosen.result.content.reason}}</p><div class="card-grid"><article v-for="a in chosen.result.assets" :key="a.id" class="asset-card"><el-image v-if="a.mime.startsWith('image/')" :src="client.assetURL(a.id)" fit="contain" :preview-src-list="[client.assetURL(a.id)]"/><video v-else-if="a.mime==='video/mp4'" :src="client.assetURL(a.id)" controls style="width:100%" preload="metadata"/><a :href="client.assetURL(a.id)" :download="a.name">{{a.name}}</a></article></div><details><summary>修改文案 / 分镜后重新渲染</summary><el-input v-model="review" type="textarea" :rows="12"/><el-button :disabled="busy" @click="renderEdited">保存修改并重新渲染</el-button></details><div class="actions"><a :href="client.base+'/api/v1/materials/'+chosen.id+'/export'" download="product-materials.zip"><el-button>导出全部素材 ZIP</el-button></a><el-checkbox v-model="confirmed">已核对参数、文案与图片</el-checkbox><el-button type="primary" :loading="busy" :disabled="!confirmed" @click="draft">写入指定账号小红书草稿</el-button></div></template></div>
 </template>
 <template v-else>
  <div class="panel business-form"><div class="section-title"><h2>客户线索与意向</h2><a :href="client.base+'/api/v1/business/leads.csv'" download="leads.csv"><el-button>导出客户 CSV</el-button></a></div><p class="subtle">意向为模型依据原话做出的判断；没有明确展示的联系方式留空。列表展示最近 2000 条记录，CSV 导出全部线索。</p><el-table :data="leads"><el-table-column prop="account" label="账号"/><el-table-column label="客户 / 联系方式"><template #default="{row}">{{row.record.name}}<br/>{{row.record.contact||'未提供'}}</template></el-table-column><el-table-column label="意向"><template #default="{row}">{{intent[row.record.intent]}}</template></el-table-column><el-table-column label="需求与依据" min-width="220"><template #default="{row}">{{row.record.evidence}}<br/><small>{{row.record.reason}}</small></template></el-table-column><el-table-column label="来源 / 证据"><template #default="{row}">{{row.record.source}}<br/><a :href="client.assetURL(row.asset_id)" target="_blank" rel="noopener">页面截图</a></template></el-table-column></el-table></div>
  <div v-if="page==='growth'" class="panel business-form"><h2>热门帖与图文参考</h2><el-table :data="visibleRecords.filter(r=>r.record.kind==='post'||r.record.kind==='note')"><el-table-column label="类型"><template #default="{row}">{{row.record.kind}}</template></el-table-column><el-table-column label="标题 / 原文"><template #default="{row}">{{row.record.title||row.record.evidence}}</template></el-table-column><el-table-column label="热度口径 / 来源"><template #default="{row}">{{row.record.reason}}<br/>{{row.record.source}}</template></el-table-column></el-table></div>
  <div class="panel business-form"><h2>发送记录</h2><el-table :data="visibleOutreach"><el-table-column prop="recipient" label="对象"/><el-table-column label="内容"><template #default="{row}">{{row.record.body}}</template></el-table-column><el-table-column prop="status" label="状态"/><el-table-column prop="created_at" label="时间"/></el-table><p class="subtle">reported 表示手机动作已回报，仍需核对页面；reserved / uncertain 不会自动重发。</p></div>
  <div class="panel business-form"><h2>定时运营计划</h2><el-table :data="visibleCampaigns"><el-table-column prop="name" label="计划"/><el-table-column prop="interval_minutes" label="间隔 / 分钟"/><el-table-column prop="next_run" label="下次检查"/><el-table-column prop="error" label="执行问题"/><el-table-column label="操作"><template #default="{row}"><el-button :disabled="busy" @click="toggle(row)">{{row.enabled?'停用':'启用'}}</el-button></template></el-table-column></el-table></div>
 </template>
</template>
<style scoped>
.business-form{padding:24px;margin-bottom:24px}.business-form .el-select{width:100%}.business-form details{margin:20px 0}.business-form .actions{display:flex;align-items:center;gap:14px;flex-wrap:wrap}.business-form .card-grid{margin:20px 0}.asset-card a{display:block;padding:12px;overflow-wrap:anywhere}
</style>
